django-queryset-filter.solution:
_OPS = {"exact", "iexact", "contains", "icontains", "gt", "gte", "lt", "lte", "in", "isnull", "startswith", "range"}


def _split(key):
    parts = key.split("__")
    if len(parts) > 1 and parts[-1] in _OPS:
        return parts[:-1], parts[-1]
    return parts, "exact"


def _value(row, path):
    cur = row
    for part in path:
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return None
    return cur


def _test(value, op, arg):
    if op == "isnull":
        return (value is None) == arg
    if value is None:
        return op == "exact" and arg is None
    if op == "exact":
        return value == arg
    if op == "iexact":
        return str(value).lower() == str(arg).lower()
    if op == "contains":
        return str(arg) in str(value)
    if op == "icontains":
        return str(arg).lower() in str(value).lower()
    if op == "startswith":
        return str(value).startswith(str(arg))
    if op == "gt":
        return value > arg
    if op == "gte":
        return value >= arg
    if op == "lt":
        return value < arg
    if op == "lte":
        return value <= arg
    if op == "in":
        return value in arg
    if op == "range":
        return arg[0] <= value <= arg[1]
    return False


def _matches(row, conditions):
    for key, arg in conditions.items():
        path, op = _split(key)
        if not _test(_value(row, path), op, arg):
            return False
    return True


def qs_filter(rows, conditions):
    return [row for row in rows if _matches(row, conditions)]

django-queryset-shape.solution:
_OPS = {"gt", "gte", "lt", "lte", "in", "contains"}


def _get(row, key):
    cur = row
    for part in key.split("__"):
        cur = cur[part]
    return cur


def _holds(row, key, arg):
    parts = key.split("__")
    op = "exact"
    if len(parts) > 1 and parts[-1] in _OPS:
        op = parts.pop()
    value = _get(row, "__".join(parts))
    if op == "exact":
        return value == arg
    if op == "gt":
        return value > arg
    if op == "gte":
        return value >= arg
    if op == "lt":
        return value < arg
    if op == "lte":
        return value <= arg
    if op == "in":
        return value in arg
    return arg in value


def _all(row, cond):
    return all(_holds(row, k, a) for k, a in cond.items())


def run_query(rows, ops):
    cur = list(rows)
    for op in ops:
        name = op[0]
        if name == "filter":
            cur = [r for r in cur if _all(r, op[1])]
        elif name == "exclude":
            cur = [r for r in cur if not _all(r, op[1])]
        elif name == "order_by":
            for key in reversed(op[1]):
                desc = key.startswith("-")
                field = key[1:] if desc else key
                cur = sorted(cur, key=lambda r: _get(r, field), reverse=desc)
                if desc:
                    # sorted(reverse=True) keeps equal items in original order, which is what we need
                    pass
        elif name == "reverse":
            cur = cur[::-1]
        elif name == "values":
            cur = [{f: _get(r, f) for f in op[1]} for r in cur]
        elif name == "values_list":
            cur = [[_get(r, f) for f in op[1]] for r in cur]
        elif name == "values_list_flat":
            cur = [_get(r, op[1]) for r in cur]
        elif name == "distinct":
            seen, out = [], []
            for r in cur:
                if r not in seen:
                    seen.append(r)
                    out.append(r)
            cur = out
    return cur

