_OPS = {"gt", "gte", "lt", "lte", "in", "icontains", "isnull"}


def _leaf(row, key, arg):
    parts = key.split("__")
    op = "exact"
    if len(parts) > 1 and parts[-1] in _OPS:
        op = parts.pop()
    value = row
    for part in parts:
        if isinstance(value, dict) and part in value:
            value = value[part]
        else:
            value = None
            break
    if op == "isnull":
        return (value is None) == arg
    if value is None:
        return op == "exact" and arg is None
    if op == "exact":
        return value == arg
    if op == "gt":
        return value > arg
    if op == "gte":
        return value >= arg
    if op == "lt":
        return value < arg
    if op == "lte":
        return value <= arg
    if op == "in":
        return value in arg
    return str(arg).lower() in str(value).lower()


def _eval(row, q):
    if isinstance(q, dict):
        return all(_leaf(row, k, a) for k, a in q.items())
    if q[0] == "AND":
        return all(_eval(row, child) for child in q[1:])
    if q[0] == "OR":
        return any(_eval(row, child) for child in q[1:])
    return not _eval(row, q[1])


def q_filter(rows, q):
    return [row for row in rows if _eval(row, q)]

django-f-update.solution:
def _match(row, where):
    for key, arg in where.items():
        field, _, op = key.partition("__")
        value = row[field]
        if op == "" and value != arg:
            return False
        if op == "gt" and not value > arg:
            return False
        if op == "gte" and not value >= arg:
            return False
        if op == "lt" and not value < arg:
            return False
        if op == "lte" and not value <= arg:
            return False
    return True


def _calc(expr, old):
    if not isinstance(expr, list):
        return expr
    if expr[0] == "F":
        return old[expr[1]]
    left, right = _calc(expr[1], old), _calc(expr[2], old)
    if expr[0] == "+":
        return left + right
    if expr[0] == "-":
        return left - right
    return left * right


def apply_update(rows, where, assignments):
    count, out = 0, []
    for row in rows:
        if _match(row, where):
            count += 1
            new = dict(row)
            for field, expr in assignments.items():
                new[field] = _calc(expr, row)
            out.append(new)
        else:
            out.append(dict(row))
    return [count, out]

django-annotate.solution:
def annotate(rows, group_key, aggregates):
    groups = {}
    for row in rows:
        groups.setdefault(row[group_key], []).append(row)
    out = []
    for key, members in groups.items():
        result = {group_key: key}
        for alias, (func, field) in aggregates.items():
            if func == "Count" and field == "*":
                result[alias] = len(members)
                continue
            values = [m[field] for m in members if m.get(field) is not None]
            if func == "Count":
                result[alias] = len(values)
            elif not values:
                result[alias] = None
            elif func == "Sum":
                result[alias] = sum(values)
            elif func == "Avg":
                result[alias] = round(sum(values) / len(values), 4)
            elif func == "Min":
                result[alias] = min(values)
            else:
                result[alias] = max(values)
        out.append(result)
    return out

django-n-plus-one.solution:
import re


def _normalise(sql):
    sql = sql.strip()
    if sql.endswith(";"):
        sql = sql[:-1].rstrip()
    sql = re.sub(r"'[^']*'", "?", sql)
    return re.sub(r"\b\d+\b", "?", sql)


def detect_n_plus_one(log, threshold):
    counts = {}
    for sql in log:
        template = _normalise(sql)
        counts[template] = counts.get(template, 0) + 1
    report = []
    for template, count in counts.items():
        if count < threshold:
            continue
        if template.endswith(" WHERE id = ?"):
            fix = "select_related"
        elif template.endswith("_id = ?"):
            fix = "prefetch_related"
        else:
            fix = "review"
        report.append([template, count, fix])
    return report

django-related-query-count.solution:
def count_queries(n, relations, accessed, select_related, prefetch_related):
    for name in list(select_related) + list(prefetch_related):
        if name not in relations:
            return -1
    for name in select_related:
        if relations[name] == "many":
            return -1
    total = 1
    for name in relations:
        if name in prefetch_related:
            total += 1 if n > 0 else 0
        elif name in select_related:
            total += 0
        elif name in accessed:
            total += n
    return total

django-migration-order.solution:
import heapq


def plan(graph):
    indegree = {node: 0 for node in graph}
    dependants = {node: [] for node in graph}
    for node, deps in graph.items():
        for dep in set(deps):
            if dep not in graph:
                return None
            indegree[node] += 1
            dependants[dep].append(node)
    ready = [node for node, d in indegree.items() if d == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for nxt in dependants[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(ready, nxt)
    return order if len(order) == len(graph) else None

django-migration-squash.solution:
def _find(out, kinds, model, field=None):
    for i, op in enumerate(out):
        if op[0] in kinds and op[1] == model and (field is None or op[2] == field):
            return i
    return -1


def squash(ops):
    out = []
    for op in ops:
        kind, model = op[0], op[1]
        created = _find(out, ("CreateModel",), model)
        if created >= 0:
            fields = out[created][2]
            if kind in ("AddField", "AlterField"):
                fields[op[2]] = op[3]
            elif kind == "RemoveField":
                fields.pop(op[2], None)
            elif kind == "RenameField":
                out[created][2] = {(op[3] if k == op[2] else k): v for k, v in fields.items()}
            elif kind == "DeleteModel":
                del out[created]
            continue
        if kind == "CreateModel":
            out.append(["CreateModel", model, dict(op[2])])
        elif kind == "AddField":
            out.append(list(op))
        elif kind == "AlterField":
            i = _find(out, ("AddField", "AlterField"), model, op[2])
            if i >= 0:
                out[i][3] = op[3]
            else:
                out.append(list(op))
        elif kind == "RemoveField":
            i = _find(out, ("AddField",), model, op[2])
            if i >= 0:
                del out[i]
            else:
                out = [o for o in out if not (o[0] == "AlterField" and o[1] == model and o[2] == op[2])]
                out.append(list(op))
        elif kind == "RenameField":
            i = _find(out, ("AddField",), model, op[2])
            if i >= 0:
                out[i][2] = op[3]
            else:
                out.append(list(op))
        elif kind == "DeleteModel":
            out = [o for o in out if o[1] != model]
            out.append(list(op))
    return out

django-form-validate.solution:
import re


def _email_ok(value):
    if re.search(r"\s", value) or value.count("@") != 1:
        return False
    local, domain = value.split("@")
    labels = domain.split(".")
    return bool(local) and len(labels) >= 2 and all(labels)


def validate_form(data, fields):
    cleaned, errors = {}, {}
    for name, rule in fields.items():
        value = data.get(name, "").strip()
        kind = rule["type"]
        if value == "":
            if rule.get("required", True):
                errors[name] = ["This field is required."]
            else:
                cleaned[name] = None if kind == "int" else ""
            continue
        if kind == "char":
            n = len(value)
            if "min_length" in rule and n < rule["min_length"]:
                errors[name] = ["Ensure this value has at least %d characters (it has %d)." % (rule["min_length"], n)]
            elif "max_length" in rule and n > rule["max_length"]:
                errors[name] = ["Ensure this value has at most %d characters (it has %d)." % (rule["max_length"], n)]
            else:
                cleaned[name] = value
        elif kind == "int":
            if not re.fullmatch(r"-?[0-9]+", value):
                errors[name] = ["Enter a whole number."]
                continue
            v = int(value)
            if "min_value" in rule and v < rule["min_value"]:
                errors[name] = ["Ensure this value is greater than or equal to %d." % rule["min_value"]]
            elif "max_value" in rule and v > rule["max_value"]:
                errors[name] = ["Ensure this value is less than or equal to %d." % rule["max_value"]]
            else:
                cleaned[name] = v
        elif kind == "email":
            if _email_ok(value):
                cleaned[name] = value
            else:
                errors[name] = ["Enter a valid email address."]
        else:
            if value in rule["choices"]:
                cleaned[name] = value
            else:
                errors[name] = ["Select a valid choice. %s is not one of the available choices." % value]
    return [not errors, cleaned, errors]

django-modelform-fields.solution:
_MAP = {
    "CharField": "CharField", "TextField": "CharField", "SlugField": "SlugField", "EmailField": "EmailField",
    "IntegerField": "IntegerField", "BooleanField": "BooleanField", "DateField": "DateField",
    "DateTimeField": "DateTimeField", "ForeignKey": "ModelChoiceField", "ManyToManyField": "ModelMultipleChoiceField",
}


def _editable(f):
    if f["type"] in ("AutoField", "BigAutoField"):
        return False
    return f.get("editable", True) and not f.get("auto_now") and not f.get("auto_now_add")


def form_fields(model, fields, exclude):
    if fields is None and exclude is None:
        return None
    by_name = {f["name"]: f for f in model if _editable(f)}
    if isinstance(fields, list):
        for name in fields:
            if name not in by_name:
                return None
        names = list(fields)
    else:
        names = list(by_name)
    skip = set(exclude or [])
    out = []
    for name in names:
        if name in skip:
            continue
        f = by_name[name]
        cls = _MAP[f["type"]]
        if f["type"] in ("CharField", "TextField") and f.get("choices"):
            cls = "TypedChoiceField"
        required = False if f["type"] == "BooleanField" else not f.get("blank", False)
        out.append([name, cls, required])
    return out

django-csrf-compare.solution:
import hmac
import string

CHARS = string.ascii_letters + string.digits


def csrf_ok(token, secret):
    if not isinstance(token, str) or any(c not in CHARS for c in token):
        return False
    if len(token) == 64:
        mask, cipher = token[:32], token[32:]
        token = "".join(CHARS[(CHARS.index(c) - CHARS.index(m)) % len(CHARS)] for c, m in zip(cipher, mask))
    elif len(token) != 32:
        return False
    return hmac.compare_digest(token, secret)

